export function tryConsumeWebSearchQuota(db: DB, day: string, cap: number): boolean {
  const info = db
    .prepare(
      `INSERT INTO web_search_quota (day, count) VALUES (?, 1)
       ON CONFLICT(day) DO UPDATE SET count = count + 1 WHERE count < ?`,
    )
    .run(day, cap);
  return info.changes > 0;
}

